window.docContents[138].resolve({"/2___-Basic-notions-of-representation-theory/2___5___-Quotients/Indecomposable-quotient-representation-of-polynomial-algebra/#Chapter2___Problem2___5___1":{"contents":"Problem 2.5.1. Let A = k[x_1, \\ldots, x_n] and let I \\neq A be any ideal in A containing all homogeneous polynomials of degree \\geq N. Show that A/I is an indecomposable representation of A.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.5. Quotients\tIndecomposable quotient representation of polynomial algebra","header":"Indecomposable quotient representation of polynomial algebra","id":"/2___-Basic-notions-of-representation-theory/2___5___-Quotients/Indecomposable-quotient-representation-of-polynomial-algebra/#Chapter2___Problem2___5___1"},"/3___-General-results-of-representation-theory/3___7___-The-Jordan-Holder-theorem/#chapter-03___section-3-7":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory","header":"3.7. The Jordan-Holder theorem","id":"/3___-General-results-of-representation-theory/3___7___-The-Jordan-Holder-theorem/#chapter-03___section-3-7"},"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Quaternionic-representations-are-even-dimensional/#Chapter5___Discussion_after_Definition5___1___1":{"contents":"In particular, note that every quaternionic representation is even-dimensional.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.1. Frobenius-Schur indicator\tQuaternionic representations are even-dimensional","header":"Quaternionic representations are even-dimensional","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Quaternionic-representations-are-even-dimensional/#Chapter5___Discussion_after_Definition5___1___1"},"/6___-Quiver-representations/#chapter-06":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory","header":"6. Quiver representations","id":"/6___-Quiver-representations/#chapter-06"},"/6___-Quiver-representations/6___4___-Roots/Section-6___4-heading-and-setup/#Chapter6___Section6___4_heading___heading-1":{"contents":"From now on, let \\Gamma be a fixed graph of type A_n, D_n, E_6, E_7, E_8. We denote the adjacency matrix of \\Gamma by R.\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.4. Roots\tSection 6.4 heading and setup","header":"6.4. Roots","id":"/6___-Quiver-representations/6___4___-Roots/Section-6___4-heading-and-setup/#Chapter6___Section6___4_heading___heading-1"},"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Section-7___1___-The-definition-of-a-category/#Chapter7___Introduction_7___1":{"contents":"\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.1. The definition of a category\tSection 7.1: The definition of a category","header":"Section 7.1: The definition of a category","id":"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Section-7___1___-The-definition-of-a-category/#Chapter7___Introduction_7___1"},"/9___-Structure-of-finite-dimensional-algebras/9___7___-Morita-equivalence/Uniqueness-of-basic-algebra-for-finite-abelian-categories/#Chapter9___Corollary9___7___3":{"contents":"Corollary 9.7.3. (i) Any finite abelian category \\mathcal{C} is equivalent to the category of finite dimensional modules over a unique basic algebra B = B(\\mathcal{C}).\n\n(ii) Any finite dimensional algebra A is Morita equivalent to a unique basic algebra B = B_A, such that \\dim B_A \\leq \\dim A.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.7. Morita equivalence\tUniqueness of basic algebra for finite abelian categories","header":"Uniqueness of basic algebra for finite abelian categories","id":"/9___-Structure-of-finite-dimensional-algebras/9___7___-Morita-equivalence/Uniqueness-of-basic-algebra-for-finite-abelian-categories/#Chapter9___Corollary9___7___3"}});
